package com.gathin.tvhome;
import android.app.*;import android.os.*;import android.text.InputType;import android.widget.*;import java.util.*;
final class SessionEthernetUi {
 static void show(Activity a,Runnable refresh){if(!SessionSettingsUi.ready(a))return;SessionSettingsUi.read(a,SettingsSessionClient.ETHERNET_READ,new Bundle(),result->{ArrayList<Bundle> items=result.getParcelableArrayList("interfaces");if(items==null||items.isEmpty()){Toast.makeText(a,"No Ethernet adapter is connected.",Toast.LENGTH_LONG).show();return;}if(items.size()==1){edit(a,items.get(0),refresh);return;}String[] names=new String[items.size()];for(int i=0;i<names.length;i++)names[i]=items.get(i).getString("interface");final ArrayList<Bundle> entries=items;AlertDialog d=new SettingsPopup.Builder(a).setTitle("Ethernet adapter").setItems(names,(dialog,w)->edit(a,entries.get(w),refresh)).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);});}
 private static TextView label(Activity a,String value){TextView t=new TextView(a);t.setText(value);t.setTextSize(17);t.setTextColor(0xffd5dbe2);t.setPadding(0,12,0,0);return t;}
 private static void edit(Activity a,Bundle current,Runnable refresh){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,12,32,12);CheckBox fixed=new CheckBox(a);fixed.setText("Static IPv4 (off = DHCP)");fixed.setTextColor(0xfff5f5fa);fixed.setChecked("STATIC".equals(current.getString("assignment")));box.addView(fixed);String[] keys={"address","prefix","gateway","dns1","dns2"};String[] names={"IP address","Prefix length (0 - 32)","Gateway (optional)","DNS","DNS 2 (optional)"};EditText[] fields=new EditText[keys.length];for(int i=0;i<keys.length;i++){box.addView(label(a,names[i]));EditText field=new EditText(a);field.setSingleLine(true);field.setTextColor(0xfff5f5fa);field.setInputType(InputType.TYPE_CLASS_PHONE);field.setText(i==1?Integer.toString(current.getInt("prefix",24)):current.getString(keys[i],""));field.setEnabled(fixed.isChecked());box.addView(field);fields[i]=field;}fixed.setOnCheckedChangeListener((button,on)->{for(EditText field:fields)field.setEnabled(on);});String mac=current.getString("mac");if(mac!=null)box.addView(label(a,"Hardware MAC: "+mac));ScrollView scroll=new ScrollView(a);scroll.addView(box);
  AlertDialog d=new SettingsPopup.Builder(a).setTitle("IP settings - "+current.getString("interface")).setView(scroll).setPositiveButton("Apply",null).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{Bundle input=new Bundle();input.putString("interface",current.getString("interface"));input.putParcelable("config",current.getParcelable("config"));input.putBoolean("static",fixed.isChecked());if(fixed.isChecked()){SettingsSessionPolicy.ipv4(fields[0].getText().toString());int prefix=Integer.parseInt(fields[1].getText().toString());if(prefix<0||prefix>32)throw new IllegalArgumentException("Prefix must be between 0 and 32");input.putInt("prefix",prefix);for(int i:new int[]{0,2,3,4}){String value=fields[i].getText().toString();if(!value.isEmpty())SettingsSessionPolicy.ipv4(value);input.putString(keys[i],value);}}d.dismiss();SessionSettingsUi.confirm(a,"Apply Ethernet settings?","This may interrupt the connection. The original configuration is saved for restoration.",()->SessionSettingsUi.change(a,SettingsSessionClient.ETHERNET_SET,input,refresh));}catch(IllegalArgumentException invalid){fields[0].setError(invalid.getMessage());}});
 }
 private SessionEthernetUi(){}
}
